-- Idempotent original practice set for Ace Student.
-- Questions below are model-authored study material, not official MUST examination questions.
-- Adds a quiz only when the same title/course pair is absent; adds questions only to an empty quiz.
WITH quiz_seed(course_code,title,description) AS (
 VALUES
 ('BFC3125','Ace Practice · Introduction to Accounting I','Original practice questions on the accounting equation, recognition, journals and reporting. Not an official examination paper.'),
 ('BEC3101','Ace Practice · Principles of Microeconomics','Original applied questions on demand, elasticity, opportunity cost and market failure.'),
 ('BFB3100','Ace Practice · Constitution and Governance','Original conceptual questions on constitutionalism, rule of law, separation of powers and devolution.'),
 ('BFB3103','Ace Practice · Principles of Management','Original practice on management functions, delegation, planning and control.'),
 ('BFB3151','Ace Practice · Principles of Marketing','Original practice on segmentation, positioning, research and the marketing mix.'),
 ('BEC3150','Ace Practice · Principles of Macroeconomics','Original applied questions on GDP, inflation, unemployment and fiscal/monetary policy.'),
 ('BFB3250','Ace Practice · Introduction to Project Management','Original practice on scope, scheduling, risk and project control.'),
 ('BFB3251','Ace Practice · Organizational Behaviour','Original practice on motivation, teams, culture and workplace behaviour.'),
 ('BFC3226','Ace Practice · Introduction to Financial Management','Original practice on time value, liquidity, investment and cost of capital concepts.'),
 ('BFB3350','Ace Practice · Strategic Management','Original practice on strategy analysis, competitive advantage and execution.'),
 ('BFB3366','Ace Practice · International Business Management','Original practice on trade, exchange-rate exposure, market entry and cross-cultural operations.'),
 ('BFB3452','Ace Practice · Business Planning','Original practice on market validation, business models, cash flow and break-even analysis.'),
 ('BFC3400','Ace Practice · Company Law','Original conceptual questions on incorporation, separate personality, directors and company governance.'),
 ('BFC3428','Ace Practice · Computerized Accounting','Original applied questions on controls, audit trails, reconciliations and accounting systems.'),
 ('BFC3277','Ace Practice · Business Finance','Original practice on financing choices, investment appraisal and working-capital decisions.'),
 ('BFC3278','Ace Practice · Auditing and Assurance','Original practice on audit evidence, independence, internal controls and opinions.'),
 ('BFC3334','Ace Practice · Financial Systems','Original practice on financial markets, intermediaries, regulation and systemic stability.'),
 ('BFC3429','Ace Practice · International Finance','Original practice on exchange-rate exposure, hedging, international cash flows and cross-border finance.')
),
inserted_quizzes AS (
 INSERT INTO public.ace_quizzes(title,course_code,description,status)
 SELECT s.title,s.course_code,s.description,'published'
 FROM quiz_seed s
 WHERE NOT EXISTS (SELECT 1 FROM public.ace_quizzes q WHERE q.title=s.title AND q.course_code=s.course_code)
 RETURNING id,course_code,title
),
quiz_ids AS (
 SELECT id,course_code,title FROM inserted_quizzes
 UNION ALL
 SELECT q.id,q.course_code,q.title FROM public.ace_quizzes q
 JOIN quiz_seed s ON s.course_code=q.course_code AND s.title=q.title
 WHERE NOT EXISTS (SELECT 1 FROM inserted_quizzes i WHERE i.id=q.id)
),
question_seed(course_code,quiz_title,sort_order,prompt,options,correct_index,explanation) AS (
 VALUES
 -- Introduction to Accounting I
 ('BFC3125','Ace Practice · Introduction to Accounting I',1,'A proprietor contributes KSh 80,000 cash to start a business. Which statement correctly describes the immediate effect? ',ARRAY['Assets rise by KSh 80,000 and equity rises by KSh 80,000','Revenue rises by KSh 80,000 and liabilities fall','Expenses rise by KSh 80,000','Assets rise but equity is unchanged']::text[],0,'The business receives cash (an asset) and recognises the owner contribution as equity; no revenue is earned.',1),
 ('BFC3125','Ace Practice · Introduction to Accounting I',2,'Under accrual accounting, revenue from a credit sale is generally recognised when:',ARRAY['The customer eventually pays cash','The sale is earned and recognition criteria are met','The owner withdraws money','The supplier issues an invoice to the business']::text[],1,'Accrual accounting recognises earned revenue when the applicable recognition criteria are met, not simply when cash arrives.',2),
 ('BFC3125','Ace Practice · Introduction to Accounting I',3,'A business buys office supplies for cash. Which entry best records the purchase when the supplies are consumed immediately?',ARRAY['Debit supplies expense; credit cash','Debit cash; credit supplies expense','Debit capital; credit revenue','Debit accounts payable; credit cash']::text[],0,'An expense increases with a debit; cash, an asset, decreases with a credit.',3),
 ('BFC3125','Ace Practice · Introduction to Accounting I',4,'A trial balance agrees. What does this establish?',ARRAY['Every transaction is recorded correctly','No fraud has occurred','Total debits equal total credits, though some errors may remain','All assets are valued at market value']::text[],2,'A balanced trial balance checks arithmetic equality of debits and credits but does not detect every omission, classification or compensating error.',4),
 ('BFC3125','Ace Practice · Introduction to Accounting I',5,'Equipment costs KSh 120,000, has an estimated residual value of KSh 20,000 and a useful life of five years. Straight-line annual depreciation is:',ARRAY['KSh 20,000','KSh 24,000','KSh 28,000','KSh 100,000']::text[],0,'(Cost − residual value) ÷ useful life = (120,000 − 20,000) ÷ 5 = KSh 20,000 per year.',5),
 -- Microeconomics
 ('BEC3101','Ace Practice · Principles of Microeconomics',1,'If the price of tea rises and tea demand falls, with other determinants unchanged, this is best described as:',ARRAY['A movement along the demand curve','A shift of the demand curve to the right','A shift of supply to the left','A fall in consumer income by definition']::text[],0,'A change in the good’s own price produces a movement along its demand curve; a non-price determinant shifts the curve.',1),
 ('BEC3101','Ace Practice · Principles of Microeconomics',2,'A product price rises by 10% and quantity demanded falls by 20%. Using the percentage-change method, the absolute value of price elasticity of demand is:',ARRAY['0.5','1','2','10']::text[],2,'Absolute price elasticity = 20% ÷ 10% = 2, so demand is elastic over the stated change.',2),
 ('BEC3101','Ace Practice · Principles of Microeconomics',3,'A student chooses paid work instead of attending a free public lecture. The opportunity cost is best measured by:',ARRAY['Every activity the student could possibly do','The value of the best alternative forgone','Only the transport fare','The student’s total monthly income']::text[],1,'Opportunity cost is the value of the next-best alternative sacrificed.',3),
 ('BEC3101','Ace Practice · Principles of Microeconomics',4,'A factory pollutes a river but does not pay for the harm imposed on downstream residents. This is an example of:',ARRAY['A positive externality','A negative production externality','Perfect price discrimination','A public good with no market failure']::text[],1,'The production activity imposes an external cost on third parties that is not reflected fully in the producer’s private cost.',4),
 ('BEC3101','Ace Practice · Principles of Microeconomics',5,'A binding price ceiling set below the market-clearing price will normally create:',ARRAY['A surplus','A shortage','No change in quantity demanded','An automatic increase in supply']::text[],1,'At the controlled low price, quantity demanded exceeds quantity supplied, creating a shortage.',5),
 -- Constitution and Governance
 ('BFB3100','Ace Practice · Constitution and Governance',1,'The rule of law is most closely associated with the principle that:',ARRAY['Public officials may act without legal limits','Everyone, including public authorities, is subject to the law','Only written contracts are enforceable','Courts must always support the executive']::text[],1,'The rule of law requires legal accountability and constraints on the exercise of public power.',1),
 ('BFB3100','Ace Practice · Constitution and Governance',2,'Separation of powers is designed primarily to:',ARRAY['Concentrate all state power in one office','Remove all cooperation between state organs','Distribute state functions and limit excessive concentration of power','Allow the legislature to decide individual court cases']::text[],2,'Separating legislative, executive and judicial functions supports checks and balances and reduces concentration of power.',2),
 ('BFB3100','Ace Practice · Constitution and Governance',3,'In Kenya, devolution under the 2010 Constitution principally establishes:',ARRAY['Abolition of county government','National and county levels of government with constitutionally assigned functions','A single national authority for all local services','Private control of public revenue']::text[],1,'The Constitution establishes national and county governments and assigns functions to each level.',3),
 ('BFB3100','Ace Practice · Constitution and Governance',4,'Which is the strongest example of an independent judicial function?',ARRAY['A minister directs the verdict in a named case','A court decides a dispute according to law and evidence without improper interference','A judge campaigns for a litigant','A court ignores binding law whenever a case is unpopular']::text[],1,'Judicial independence requires decisions based on law and evidence, free from improper external direction.',4),
 ('BFB3100','Ace Practice · Constitution and Governance',5,'A constitution is best understood as:',ARRAY['A list of temporary departmental procedures','The foundational legal framework that structures public power and protects rights','A private agreement between two firms','An annual government budget']::text[],1,'A constitution establishes the state’s governing framework, institutions, powers and rights protections.',5),
 -- Management
 ('BFB3103','Ace Practice · Principles of Management',1,'Which management function sets objectives and chooses actions before work begins?',ARRAY['Planning','Controlling','Staffing only','Auditing']::text[],0,'Planning establishes objectives and selects courses of action to achieve them.',1),
 ('BFB3103','Ace Practice · Principles of Management',2,'A manager delegates a task to an employee. Which statement is most accurate?',ARRAY['The manager transfers every form of accountability permanently','Authority to perform specified work can be delegated, but the manager retains overall accountability','Delegation removes the need to monitor results','Delegation means the employee sets all organizational goals']::text[],1,'Delegation grants authority for specified tasks, but managers remain accountable for their area of responsibility.',2),
 ('BFB3103','Ace Practice · Principles of Management',3,'The control process usually compares actual performance against:',ARRAY['Personal preference only','Predetermined standards or objectives','Competitors’ advertising slogans','The number of meetings held']::text[],1,'Control involves setting standards, measuring actual results, comparing them and taking corrective action.',3),
 ('BFB3103','Ace Practice · Principles of Management',4,'A manager groups employees into marketing, finance and operations departments. This is an example of:',ARRAY['Functional departmentalization','Random allocation','Product diversification','External auditing']::text[],0,'Functional departmentalization groups roles by specialist function.',4),
 ('BFB3103','Ace Practice · Principles of Management',5,'Which goal is the best example of a measurable operational objective?',ARRAY['Improve customer service someday','Become the best business in Kenya','Reduce average customer response time from 24 hours to 8 hours by the end of the quarter','Work harder whenever possible']::text[],2,'The objective defines a measurable baseline, target and deadline, making progress assessable.',5),
 -- Marketing
 ('BFB3151','Ace Practice · Principles of Marketing',1,'Market segmentation means:',ARRAY['Setting one price for every product','Dividing a broad market into groups with relevant shared characteristics','Eliminating customer research','Selling only to existing customers']::text[],1,'Segmentation identifies distinct groups with different needs or behaviours that may merit different marketing approaches.',1),
 ('BFB3151','Ace Practice · Principles of Marketing',2,'A value proposition should primarily explain:',ARRAY['The benefit a target customer receives and why the offer is a suitable choice','The owner’s personal history only','The business registration number','The number of staff in the company']::text[],0,'A value proposition communicates the customer problem addressed, value delivered and differentiation.',2),
 ('BFB3151','Ace Practice · Principles of Marketing',3,'In the traditional 4Ps marketing mix, which item is NOT one of the four Ps?',ARRAY['Product','Price','Promotion','Profit']::text[],3,'The traditional 4Ps are product, price, place and promotion; profit is an outcome, not one of the four elements.',3),
 ('BFB3151','Ace Practice · Principles of Marketing',4,'A business interviews a small number of target customers to explore why they abandon checkout. This is primarily:',ARRAY['Qualitative exploratory research','A national census','A controlled production run','Financial auditing']::text[],0,'Interviews are a qualitative method useful for exploring motivations and barriers in depth.',4),
 ('BFB3151','Ace Practice · Principles of Marketing',5,'Positioning is mainly concerned with:',ARRAY['How the target market perceives an offer relative to alternatives','The physical location of the accounting office only','How inventory is counted','The company’s legal structure']::text[],0,'Positioning seeks a clear, relevant place for the offer in the target customer’s mind compared with competitors.',5),
 -- Macroeconomics
 ('BEC3150','Ace Practice · Principles of Macroeconomics',1,'Gross domestic product measures the value of:',ARRAY['All intermediate goods counted repeatedly','Final goods and services produced within a country during a period','Only exports produced by citizens abroad','All financial assets held by households']::text[],1,'GDP measures final production within a country’s economic territory over a specified period.',1),
 ('BEC3150','Ace Practice · Principles of Macroeconomics',2,'A sustained rise in the general price level is called:',ARRAY['Deflation','Inflation','Appreciation of every currency','Economic depreciation']::text[],1,'Inflation is a sustained increase in the general level of prices.',2),
 ('BEC3150','Ace Practice · Principles of Macroeconomics',3,'A government increases spending on infrastructure while holding taxes unchanged. In the short run, this is an example of:',ARRAY['Expansionary fiscal policy','Contractionary monetary policy','A reduction in government demand','A direct exchange-rate peg']::text[],0,'Higher government expenditure is an expansionary fiscal action, other things equal.',3),
 ('BEC3150','Ace Practice · Principles of Macroeconomics',4,'The unemployment rate is generally calculated as unemployed people actively seeking work divided by:',ARRAY['The total population including children','The labour force','All employed people only','The number of firms']::text[],1,'The labour force consists of employed and unemployed people who are available and actively seeking work under the applicable statistical definition.',4),
 ('BEC3150','Ace Practice · Principles of Macroeconomics',5,'If a central bank raises its policy interest rate, the intended effect in an inflation-fighting cycle is often to:',ARRAY['Encourage unlimited borrowing immediately','Make credit more expensive and moderate aggregate demand','Guarantee that prices fall the next day','Increase every household’s disposable income']::text[],1,'Higher policy rates tend to tighten financial conditions and moderate spending; effects occur with lags and are not guaranteed.',5),
 -- Project Management
 ('BFB3250','Ace Practice · Introduction to Project Management',1,'A project differs from routine operations mainly because it is:',ARRAY['Temporary and undertaken to create a defined output or change','An activity with no objective','Always repeated identically forever','Exempt from resource constraints']::text[],0,'Projects are temporary endeavours with defined objectives, deliverables and a beginning and end.',1),
 ('BFB3250','Ace Practice · Introduction to Project Management',2,'A stakeholder register is used primarily to:',ARRAY['Record people or groups affected by or able to affect the project','Replace the project budget','List only purchased equipment','Guarantee that no risks arise']::text[],0,'Stakeholder analysis identifies relevant people/groups and supports engagement planning.',2),
 ('BFB3250','Ace Practice · Introduction to Project Management',3,'A task on the critical path is delayed by two days and no schedule recovery is possible. The project completion date will generally:',ARRAY['Move later by two days','Move earlier by two days','Remain unaffected by definition','Become equal to the project budget']::text[],0,'Critical-path activities have no total float in the baseline schedule, so a delay typically delays the project finish unless recovered.',3),
 ('BFB3250','Ace Practice · Introduction to Project Management',4,'A risk register should capture risks, their likelihood/impact and:',ARRAY['Planned responses, owners and monitoring','Only the project title','Unrelated employee hobbies','Only risks that have already occurred']::text[],0,'A useful risk register supports assessment, ownership, responses and ongoing review of uncertain events.',4),
 ('BFB3250','Ace Practice · Introduction to Project Management',5,'A change request is raised after a client adds a major feature. The best first response is to:',ARRAY['Assess the impact on scope, schedule, cost and risk through change control','Add it immediately without documenting it','Delete the original project plan','Ask the team to work unpaid overtime automatically']::text[],0,'Formal change control assesses implications and obtains the required approval before the baseline is changed.',5),
 -- Organizational Behaviour
 ('BFB3251','Ace Practice · Organizational Behaviour',1,'Organizational behaviour studies:',ARRAY['How individuals, groups and structures influence behaviour at work','Only the company’s annual tax return','Only factory machine maintenance','Only external exchange rates']::text[],0,'Organizational behaviour examines individuals, groups and organizational systems in work settings.',1),
 ('BFB3251','Ace Practice · Organizational Behaviour',2,'In Maslow’s model, which category concerns belonging, friendship and social connection?',ARRAY['Physiological needs','Safety needs','Social needs','Self-actualization']::text[],2,'Belongingness and social connection are classified as social needs in Maslow’s commonly taught hierarchy.',2),
 ('BFB3251','Ace Practice · Organizational Behaviour',3,'A team has capable members but unclear responsibilities and repeated duplicated work. The most direct intervention is to:',ARRAY['Clarify roles, responsibilities and coordination norms','Increase ambiguity','Remove all communication','Reward duplicated effort']::text[],0,'Clear roles and coordination norms reduce role ambiguity and duplicated work.',3),
 ('BFB3251','Ace Practice · Organizational Behaviour',4,'Organizational culture is best described as:',ARRAY['Shared values, assumptions and norms that shape how work is done','A company’s office paint colour alone','The legal ownership register only','A list of daily exchange rates']::text[],0,'Culture comprises shared meanings and behavioural norms that influence decisions and interactions.',4),
 ('BFB3251','Ace Practice · Organizational Behaviour',5,'Psychological safety in a team most directly means members feel able to:',ARRAY['Raise concerns and admit mistakes without unreasonable interpersonal punishment','Avoid all accountability','Ignore customer feedback','Make every decision without discussion']::text[],0,'Psychological safety supports interpersonal risk-taking, such as asking questions and reporting mistakes, while accountability remains important.',5),
 -- Financial Management
 ('BFC3226','Ace Practice · Introduction to Financial Management',1,'The time value of money means that, under positive interest and comparable risk, a sum received today is generally:',ARRAY['Worth less than the same sum received later','Worth more than the same nominal sum received later','Always equal to any future amount','Unaffected by the time of receipt']::text[],1,'Money available today can earn a return, so timing matters when comparing cash flows.',1),
 ('BFC3226','Ace Practice · Introduction to Financial Management',2,'A project has a positive net present value when:',ARRAY['The present value of expected inflows exceeds the initial and other relevant outflows','Its accounting revenue is zero','Its payback period is always the shortest possible','It has no uncertainty']::text[],0,'NPV discounts relevant cash flows and subtracts the investment cost; positive NPV indicates value creation under the assumptions used.',2),
 ('BFC3226','Ace Practice · Introduction to Financial Management',3,'Working capital is commonly defined as:',ARRAY['Current assets minus current liabilities','Total assets minus share capital only','Revenue minus tax expense','Long-term debt plus equity']::text[],0,'Net working capital is current assets less current liabilities.',3),
 ('BFC3226','Ace Practice · Introduction to Financial Management',4,'A firm’s cash budget is especially useful for assessing:',ARRAY['Whether cash receipts and payments are likely to leave a funding shortfall','The exact market value of every brand','Whether all employees are satisfied','Only the accounting depreciation method']::text[],0,'A cash budget forecasts liquidity timing and helps identify potential cash deficits or surpluses.',4),
 ('BFC3226','Ace Practice · Introduction to Financial Management',5,'Diversification can reduce portfolio risk most effectively when the assets held:',ARRAY['Have returns that are not perfectly positively correlated','All respond identically to every event','Are all issued by one borrower','Guarantee a fixed profit']::text[],0,'Combining assets with less-than-perfectly positively correlated returns can reduce portfolio variability; it does not eliminate all risk.',5),
 -- Strategic Management
 ('BFB3350','Ace Practice · Strategic Management',1,'In SWOT analysis, which item is normally an external factor?',ARRAY['A skilled internal finance team','An outdated internal process','A new market segment emerging in the economy','A company’s internal brand guidelines']::text[],2,'Opportunities and threats are external; strengths and weaknesses are internal.',1),
 ('BFB3350','Ace Practice · Strategic Management',2,'Which sequence best represents a basic strategic-management cycle?',ARRAY['Analyse situation, formulate strategy, implement, evaluate and adapt','Implement first, then decide the objective years later','Set a slogan, then ignore performance','Audit payroll, then automatically choose a market']::text[],0,'Strategy requires diagnosis, choice, execution and monitoring/adaptation.',2),
 ('BFB3350','Ace Practice · Strategic Management',3,'A capability is more likely to support sustained competitive advantage when it is valuable, difficult to imitate and:',ARRAY['Organized so the firm can exploit it','Known by every competitor and freely available','Unrelated to customer needs','Easy to replace without cost']::text[],0,'Resource-based analysis asks whether resources/capabilities are valuable, rare, hard to imitate/substitute and supported by the organization.',3),
 ('BFB3350','Ace Practice · Strategic Management',4,'A balanced scorecard is intended to:',ARRAY['Assess performance across several perspectives, not financial measures alone','Replace strategy with one revenue target','Measure only inventory quantity','Guarantee that a strategy will succeed']::text[],0,'The balanced scorecard commonly considers financial, customer, internal-process and learning/growth perspectives.',4),
 ('BFB3350','Ace Practice · Strategic Management',5,'A company’s strategy has strong targets but repeatedly misses delivery because teams lack clear owners. The most immediate weakness is in:',ARRAY['Strategy implementation and accountability','External market segmentation only','The definition of inflation','The company’s legal incorporation']::text[],0,'Execution needs clear ownership, resources, communication and feedback—not just well-written objectives.',5),
 -- International Business Management
 ('BFB3366','Ace Practice · International Business Management',1,'Comparative advantage suggests a country or firm should specialise relatively more in goods for which it has:',ARRAY['A lower opportunity cost','The highest absolute cost','No available workers','A guaranteed monopoly']::text[],0,'Comparative advantage is based on lower opportunity cost, not necessarily absolute productivity advantage.',1),
 ('BFB3366','Ace Practice · International Business Management',2,'A Kenyan importer must pay a supplier in US dollars in three months. If the dollar strengthens against the shilling, the shilling cost of the invoice will generally:',ARRAY['Rise','Fall to zero','Remain fixed regardless of the exchange rate','Convert automatically into revenue']::text[],0,'A stronger dollar means more shillings are needed to buy the same dollar amount, all else equal.',2),
 ('BFB3366','Ace Practice · International Business Management',3,'Direct exporting is different from foreign direct investment because direct exporting primarily involves:',ARRAY['Selling goods into a foreign market without necessarily owning productive assets there','Buying a controlling stake in a foreign factory in every case','Avoiding all border procedures','Selling only to domestic customers']::text[],0,'Exporting serves a foreign market from a home or third-country production base; FDI entails a lasting ownership/control interest abroad.',3),
 ('BFB3366','Ace Practice · International Business Management',4,'A tariff is generally:',ARRAY['A tax or duty on imported or exported goods, most commonly imports','A voluntary staff-training plan','A company’s annual dividend','A measure of employee turnover']::text[],0,'Tariffs are customs duties applied to goods crossing a border, commonly imports.',4),
 ('BFB3366','Ace Practice · International Business Management',5,'A company entering a new country finds that customers interpret its advertising differently because of local norms. The strongest response is to:',ARRAY['Research local context and adapt communication while preserving the core brand promise','Assume consumer preferences are identical everywhere','Stop collecting customer feedback','Translate words literally without testing meaning']::text[],0,'Cross-cultural research and local adaptation reduce misinterpretation and improve market fit.',5),
 -- Business Planning
 ('BFB3452','Ace Practice · Business Planning',1,'Why is an executive summary often finalised after the rest of a business plan is drafted?',ARRAY['It must accurately summarise the completed analysis and plan','It replaces the financial forecasts','It is legally required to be the longest section','It is written only after the business closes']::text[],0,'Writing it last helps ensure the summary reflects the actual market, operating and financial plan.',1),
 ('BFB3452','Ace Practice · Business Planning',2,'A product sells for KSh 500, has variable cost of KSh 300 per unit and fixed costs of KSh 40,000. The break-even sales volume is:',ARRAY['80 units','100 units','200 units','400 units']::text[],2,'Contribution per unit = 500 − 300 = KSh 200. Break-even volume = 40,000 ÷ 200 = 200 units.',2),
 ('BFB3452','Ace Practice · Business Planning',3,'A cash-flow forecast differs from a profit forecast because cash flow focuses on:',ARRAY['Timing of actual cash receipts and payments','Only brand awareness','Only accounting profit irrespective of payment timing','The number of competitors']::text[],0,'A profitable business can still run short of cash when receipts and payments occur at different times.',3),
 ('BFB3452','Ace Practice · Business Planning',4,'Before investing heavily in production, an entrepreneur interviews target buyers and tests willingness to pay. This primarily reduces uncertainty about:',ARRAY['Market demand and customer validation','The colour of accounting ledgers','The company’s historical depreciation only','The exact future exchange rate']::text[],0,'Customer discovery and willingness-to-pay tests help validate demand before committing significant resources.',4),
 ('BFB3452','Ace Practice · Business Planning',5,'A useful business-plan assumption should be:',ARRAY['Explicit, evidence-based where possible, and tested for sensitivity','Hidden so reviewers cannot question it','Chosen only because it creates the highest forecast profit','Never updated after launch']::text[],0,'Transparent assumptions can be challenged, tested against scenarios and revised as evidence changes.',5),
 -- Company Law
 ('BFC3400','Ace Practice · Company Law',1,'The doctrine of separate legal personality generally means an incorporated company:',ARRAY['Has a legal identity distinct from its members','Is identical to every shareholder personally','Cannot own property','Has no capacity to enter contracts']::text[],0,'A company is generally a separate legal person from its shareholders, subject to applicable law and exceptions.',1),
 ('BFC3400','Ace Practice · Company Law',2,'Limited liability for a shareholder in a company limited by shares generally means liability is limited to:',ARRAY['The unpaid amount, if any, on the shares held','All personal assets in every circumstance','Any amount demanded by a competitor','The company’s entire annual turnover']::text[],0,'In a company limited by shares, a member’s liability is generally limited to any unpaid amount on their shares, subject to legal exceptions.',2),
 ('BFC3400','Ace Practice · Company Law',3,'A director’s duty to promote the success of the company is most consistent with:',ARRAY['Acting in good faith for the company’s benefit while considering relevant statutory factors','Using company property for undisclosed personal benefit','Following any instruction even if unlawful','Ignoring conflicts of interest']::text[],0,'Directors must comply with statutory and fiduciary duties, including good-faith decision-making for the company’s benefit.',3),
 ('BFC3400','Ace Practice · Company Law',4,'Why should a director disclose a relevant personal interest in a proposed company transaction?',ARRAY['To enable transparent management of conflicts under applicable law','To automatically cancel every contract','To transfer the company’s debts to employees','To avoid keeping any company records']::text[],0,'Disclosure enables conflicts to be managed in accordance with the company’s constitution and applicable law.',4),
 ('BFC3400','Ace Practice · Company Law',5,'A company’s articles of association generally address:',ARRAY['Internal governance rules and how the company is managed','The daily market exchange rate','The personal curriculum of each shareholder','The tax rate for every country']::text[],0,'Articles typically govern internal matters such as decision-making, meetings, directors and member rights, subject to statute.',5),
 -- Computerized Accounting
 ('BFC3428','Ace Practice · Computerized Accounting',1,'Why is an audit trail important in computerized accounting?',ARRAY['It helps trace transactions from source documents through processing to reports','It removes the need for backups','It prevents every possible fraud automatically','It allows all staff to share one password']::text[],0,'An audit trail supports traceability, review and investigation of how transactions were entered and processed.',1),
 ('BFC3428','Ace Practice · Computerized Accounting',2,'Which control best reduces the risk that one employee can create a supplier and approve a payment to that supplier without review?',ARRAY['Segregation of duties and independent approval','Giving every employee administrator rights','Disabling transaction logs','Sharing one generic account']::text[],0,'Separating incompatible duties and requiring independent approval reduces opportunities for error and fraud.',2),
 ('BFC3428','Ace Practice · Computerized Accounting',3,'A bank reconciliation identifies a difference between the bank statement and the cash-book balance. The best next step is to:',ARRAY['Investigate timing differences and errors, then record valid adjustments','Delete whichever balance is lower','Assume the bank is always wrong','Change the ledger until it agrees without evidence']::text[],0,'Reconciliation explains differences such as outstanding items, bank charges and errors; adjustments require evidence.',3),
 ('BFC3428','Ace Practice · Computerized Accounting',4,'Which is the strongest basic protection against loss of accounting data after hardware failure or ransomware?',ARRAY['Regular tested backups stored separately with controlled access','A single copy saved on the same laptop','Disabling all updates permanently','Allowing unrestricted shared logins']::text[],0,'Separate, access-controlled and tested backups improve recovery from device failure or compromise.',4),
 ('BFC3428','Ace Practice · Computerized Accounting',5,'A computerized accounting system produces a balanced trial balance, but a transaction was never entered. Why might the error remain undetected?',ARRAY['A complete omission may leave total debits and credits equally understated','The system always detects missing transactions automatically','Every omission changes the exchange rate','A balanced trial balance proves all transactions were entered']::text[],0,'A transaction omitted entirely affects neither side, so debit-credit equality can remain while records are incomplete.',5),
 -- Business Finance
 ('BFC3277','Ace Practice · Business Finance',1,'Which statement best distinguishes debt finance from ordinary equity finance?',ARRAY['Debt normally creates contractual repayment obligations; equity represents an ownership claim','Debt always has no cost and equity always has a fixed interest rate','Equity must always be repaid on a fixed date','Debt holders always own the company']::text[],0,'Debt generally creates contractual payment obligations, while equity holders own a residual interest and returns are not fixed in the same way.',1),
 ('BFC3277','Ace Practice · Business Finance',2,'A project costs KSh 100,000 today and has expected discounted future net cash inflows with a present value of KSh 118,000. Its net present value is:',ARRAY['−KSh 18,000','KSh 18,000','KSh 100,000','KSh 118,000']::text[],1,'NPV = present value of future net cash flows − initial investment = 118,000 − 100,000 = KSh 18,000.',2),
 ('BFC3277','Ace Practice · Business Finance',3,'Why might excessive investment in inventory weaken a firm’s financial position?',ARRAY['It ties up cash and can increase storage, damage and obsolescence costs','It always increases cash immediately','It eliminates all operating risk','It automatically reduces accounts payable to zero']::text[],0,'Excess inventory ties up working capital and can generate carrying costs and losses from deterioration or obsolescence.',3),
 ('BFC3277','Ace Practice · Business Finance',4,'Financial leverage increases when a company relies more heavily on:',ARRAY['Fixed-cost financing such as debt','Retained earnings only with no fixed obligations','Customer feedback','Non-financial performance indicators']::text[],0,'Debt and other fixed financing commitments can magnify returns to equity and financial risk.',4),
 ('BFC3277','Ace Practice · Business Finance',5,'A cash budget is showing a likely shortfall next month despite forecast accounting profit. The most useful first response is to:',ARRAY['Examine receipt and payment timing and plan liquidity actions','Ignore it because profit guarantees cash','Record forecast sales as cash received today','Stop preparing financial reports']::text[],0,'Profit and cash timing differ; receivables, payables, inventory and planned financing should be examined to manage liquidity.',5),
 -- Auditing and Assurance
 ('BFC3278','Ace Practice · Auditing and Assurance',1,'The primary purpose of an independent external audit of financial statements is to:',ARRAY['Express an opinion on whether the statements are fairly presented in all material respects under the applicable framework','Guarantee the entity will remain profitable','Prepare every transaction for management','Detect every instance of fraud with certainty']::text[],0,'An audit provides reasonable assurance and an opinion; it is not a guarantee of future viability or detection of every fraud.',1),
 ('BFC3278','Ace Practice · Auditing and Assurance',2,'Which combination best describes sufficient appropriate audit evidence?',ARRAY['Enough evidence that is relevant and reliable for the audit conclusion','Only verbal assurances from the finance director','The largest possible number of irrelevant documents','Evidence selected only because it supports management']::text[],0,'Sufficiency concerns quantity; appropriateness concerns relevance and reliability.',2),
 ('BFC3278','Ace Practice · Auditing and Assurance',3,'Why is auditor independence important?',ARRAY['It supports objective judgment and public confidence in the audit opinion','It allows the auditor to manage the client’s daily operations','It removes the need to gather evidence','It guarantees the client has no errors']::text[],0,'Independence reduces threats to objectivity and supports credibility of the auditor’s conclusions.',3),
 ('BFC3278','Ace Practice · Auditing and Assurance',4,'Which control best separates incompatible duties?',ARRAY['One employee authorizes payments, another records them, and another handles cash where practicable','One employee creates vendors, approves invoices and releases payments without review','All staff use the same administrator password','Transaction logs are disabled']::text[],0,'Segregating authorization, recording and custody reduces the ability to commit and conceal errors or fraud.',4),
 ('BFC3278','Ace Practice · Auditing and Assurance',5,'An auditor concludes that the financial statements are materially misstated and management does not correct the issue. The auditor should:',ARRAY['Consider the appropriate modified opinion based on the nature and pervasiveness of the misstatement','Issue an unmodified opinion regardless of materiality','Delete the audit evidence','Replace the financial statements without authorization']::text[],0,'Material uncorrected misstatements may require a qualified or adverse opinion depending on pervasiveness and the applicable standards.',5),
 -- Financial Systems
 ('BFC3334','Ace Practice · Financial Systems',1,'A financial system primarily helps an economy by:',ARRAY['Channeling funds between savers and users of funds and supporting payments and risk transfer','Eliminating every form of uncertainty','Replacing all goods markets','Guaranteeing positive returns to every investor']::text[],0,'Financial systems connect savers and borrowers, support payments, price risk and facilitate allocation of capital.',1),
 ('BFC3334','Ace Practice · Financial Systems',2,'Money markets primarily deal in:',ARRAY['Short-term debt instruments and liquidity management','Only long-term ownership shares','Only residential property','Goods sold directly to households']::text[],0,'Money markets focus on short-term borrowing/lending instruments and liquidity, while capital markets support longer-term finance.',2),
 ('BFC3334','Ace Practice · Financial Systems',3,'A financial intermediary such as a bank can support the economy by:',ARRAY['Pooling deposits and evaluating borrowers, helping reduce transaction and information costs','Guaranteeing that every borrower repays','Eliminating the need for regulation','Creating unlimited real resources from accounting entries']::text[],0,'Intermediaries pool funds, screen and monitor borrowers and facilitate transactions, although credit risk remains.',3),
 ('BFC3334','Ace Practice · Financial Systems',4,'Why do financial regulators monitor banks and other financial institutions?',ARRAY['To support stability, protect customers and promote integrity and compliance','To guarantee every investor a profit','To set the price of every good in the economy','To remove all competition between providers']::text[],0,'Regulation seeks to address systemic risk, protect consumers and support lawful and sound financial activity.',4),
 ('BFC3334','Ace Practice · Financial Systems',5,'A rise in market interest rates will generally reduce the market price of an existing fixed-rate bond, all else equal, because:',ARRAY['Its fixed payments are discounted at a higher required return','Its coupon payments automatically double','The issuer’s debt disappears','The bond becomes a share']::text[],0,'When market yields rise, existing fixed coupons are less attractive, so bond prices fall until their yield is competitive.',5),
 -- International Finance
 ('BFC3429','Ace Practice · International Finance',1,'A Kenyan firm must pay US$20,000 in three months. The main transaction exposure is that:',ARRAY['Exchange-rate changes may alter the shilling cost of the future dollar payment','The invoice amount will automatically become revenue','The exchange rate cannot change before payment','The firm has no cash-flow risk if the contract is in dollars']::text[],0,'A foreign-currency payable creates transaction exposure because the domestic-currency amount required at settlement can change.',1),
 ('BFC3429','Ace Practice · International Finance',2,'If a Kenyan exporter expects to receive US dollars later and wants to lock in a conversion rate today, a common instrument is a:',ARRAY['Forward exchange contract','Ordinary share split','Warehouse receipt','Fixed-asset depreciation schedule']::text[],0,'A forward contract can set an agreed exchange rate for a specified future currency exchange, subject to its terms and counterparty risk.',2),
 ('BFC3429','Ace Practice · International Finance',3,'A currency depreciates against another currency. All else equal, the depreciating currency’s exports may become:',ARRAY['Cheaper to foreign buyers in their currency','Automatically illegal','More expensive to every foreign buyer','Unaffected under every pricing arrangement']::text[],0,'Depreciation can lower foreign-currency export prices if exporters pass through the exchange-rate change; actual effects depend on pricing and contracts.',3),
 ('BFC3429','Ace Practice · International Finance',4,'Which exposure arises when translating a foreign subsidiary’s financial statements into the parent company’s reporting currency?',ARRAY['Translation exposure','Inventory shrinkage only','Domestic payroll exposure only','A guaranteed arbitrage profit']::text[],0,'Translation exposure arises from converting foreign operations’ accounts into the group reporting currency.',4),
 ('BFC3429','Ace Practice · International Finance',5,'Why might a firm use a currency option rather than a forward contract?',ARRAY['An option can provide a right, but not an obligation, to exchange at a specified rate in return for a premium','An option removes all currency risk at no cost','An option must always be exercised','A forward contract is a type of inventory control']::text[],0,'A currency option grants a right without an obligation to transact at the specified terms; the buyer typically pays a premium.',5)
),
questions_added AS (
 INSERT INTO public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order)
 SELECT q.id,qs.prompt,to_jsonb(qs.options),qs.correct_index,qs.explanation,qs.sort_order
 FROM question_seed qs JOIN quiz_ids q ON q.course_code=qs.course_code AND q.title=qs.quiz_title
 WHERE NOT EXISTS (SELECT 1 FROM public.ace_questions existing WHERE existing.quiz_id=q.id)
 RETURNING id
)
SELECT (SELECT count(*) FROM inserted_quizzes) AS quizzes_created,
       (SELECT count(*) FROM questions_added) AS questions_created;